import { FolderGit2, PackageCheck, Hammer, PenLine, type LucideIcon } from "lucide-react";
import { IconBox } from "@/shared/ui/data/IconBox";

type ProjectStatus = "active" | "shipped" | "in-progress" | "draft";
interface StatusFacet { value: ProjectStatus; label: string; dot: string; tone: string }
const STATUS_FACETS: StatusFacet[] = [
  { value: "active",      label: "active",      dot: "var(--success)", tone: "success" },
  { value: "shipped",     label: "shipped",     dot: "var(--fg-dim)",  tone: "neutral" },
  { value: "in-progress", label: "in progress", dot: "var(--violet)",  tone: "info" },
  { value: "draft",       label: "draft",       dot: "var(--accent)",  tone: "accent" },
];
const STATUS_META: Record<ProjectStatus, StatusFacet> =
  Object.fromEntries(STATUS_FACETS.map((f) => [f.value, f])) as Record<ProjectStatus, StatusFacet>;

const STATUS_ICON: Record<ProjectStatus, LucideIcon> = {
  active: FolderGit2, shipped: PackageCheck, "in-progress": Hammer, draft: PenLine,
};
export function StatusTile({ status = "active", big }: { status?: ProjectStatus; big?: boolean }) {
  const hue = STATUS_META[status].dot;
  const Icon = STATUS_ICON[status];
  const size = big ? 34 : 28;
  return (
    <IconBox
      size={size}
      radius={8}
      background={`color-mix(in oklch, ${hue}, transparent 88%)`}
      border={`1px solid color-mix(in oklch, ${hue}, transparent 70%)`}
      color={hue}
    >
      <Icon size={big ? 16 : 14} />
    </IconBox>
  );
}
